      <div className="text-xs mt-1.5" style={{ color: "var(--muted)" }}>{seats === 1 ? "Heads-up with the dealer" : `You + ${seats - 1} other${seats > 2 ? "s" : ""}`}{extra ? " · dashed seat is your second hand" : ""}</div>
