    setMsg(ok ? { ok: true, title: `Running count ${fmtTC(sh.current.rc)} — right.` } : { ok: false, title: `Running count is ${fmtTC(sh.current.rc)}.`, body: `You said ${fmtTC(guess)}.` });
    setPhase("bet");
