const SKILL_GO = { strategy: ["train", { trainMode: "basic" }], deviation: ["train", { trainMode: "dev" }], count: ["count", { drill: "count" }], pairs: ["count", { drill: "count" }], tc: ["count", { drill: "tc" }], totals: ["count", { drill: "totals" }], play: ["play", {}] };
// the one thing most worth practising today: a core skill you haven't tried, then your weakest under 95%,
// then anything you haven't touched this week — or, if it's all casino-ready, a shoe of live play
function FocusCard({ log, go }) {
  const pick = useMemo(() => {
    if (!log) return null;
    const now = Date.now(), wk = 7 * 864e5, m = {};
    log.forEach((e) => { const r = m[e.s] || (m[e.s] = { w: 0, ok: 0, last: 0 }); r.last = Math.max(r.last, e.t); if (e.t >= now - wk) { r.w++; r.ok += e.ok; } });
    const name = (k) => (SKILLS.find(([x]) => x === k) || [k, k])[1];
    const core = ["strategy", "count", "tc", "deviation"];
    const fresh = core.find((k) => !m[k]);
    if (!log.length) return { k: "strategy", title: "Start with basic strategy", sub: "It's the base everything else builds on. A few minutes a day locks it in.", cta: "Start" };
    if (fresh) return { k: fresh, title: `Try ${name(fresh).toLowerCase()}`, sub: "You haven't practiced this one yet.", cta: "Start" };
    const weak = Object.entries(m).filter(([, r]) => r.w >= 5).map(([k, r]) => [k, Math.round((r.ok / r.w) * 100)]).filter(([, a]) => a < 95).sort((a, b) => a[1] - b[1])[0];
    if (weak) return { k: weak[0], title: `${name(weak[0])} · ${weak[1]}%`, sub: `Your weakest skill this week. Get it to 95% to be casino-ready.`, cta: "Practice", acc: weak[1] };
    const stale = core.find((k) => m[k] && m[k].w === 0);
    if (stale) return { k: stale, title: `${name(stale)} — keep it sharp`, sub: `You haven't practiced it this week.`, cta: "Practice" };
    return { k: "play", title: "Everything's casino-ready", sub: "Play a shoe at the live table to keep it all sharp together.", cta: "Play a shoe" };
  }, [log]);
  if (!pick || !go) return null;
  return (
    <section className="card p-5 mb-4 focuscard">
      <div className="eyebrow mb-1.5" style={{ color: "var(--brass)" }}>Focus for today</div>
      <div className="flex items-center justify-between gap-3">
        <div className="min-w-0">
          <div className="text-[17px] font-semibold truncate" style={{ color: "var(--ivory)" }}>{pick.title}</div>
          <div className="text-xs mt-0.5" style={{ color: "var(--muted)" }}>{pick.sub}</div>
        </div>
        <button onClick={() => SKILL_GO[pick.k] && go(...SKILL_GO[pick.k])} className="btn shrink-0" style={{ width: "auto", padding: "0 18px", minHeight: 42 }}>{pick.cta}</button>
      </div>
    </section>
  );
}
const skillTone = (a) => a == null ? "var(--muted)" : a >= 95 ? "var(--brass)" : a >= 85 ? "var(--ivory)" : "var(--rose)";
// one row per skill you've practiced: this week's accuracy, a slim bar, and how it moved vs the week before
function SkillsCard({ log, go }) {
  const rows = useMemo(() => {
    const now = Date.now(), wk = 7 * 864e5, m = {};
    (log || []).forEach((e) => {
      const r = m[e.s] || (m[e.s] = { all: 0, allOk: 0, w: 0, wOk: 0, p: 0, pOk: 0, last: 0 });
      r.all++; r.allOk += e.ok; r.last = Math.max(r.last, e.t);
      if (e.t >= now - wk) { r.w++; r.wOk += e.ok; } else if (e.t >= now - 2 * wk) { r.p++; r.pOk += e.ok; }
    });
    return SKILLS.filter(([k]) => m[k]).map(([k, name]) => {
      const r = m[k], recent = r.w > 0;
      const acc = Math.round(((recent ? r.wOk / r.w : r.allOk / r.all)) * 100);
      const delta = recent && r.w >= 10 && r.p >= 10 ? acc - Math.round((r.pOk / r.p) * 100) : null;
      const days = Math.floor((now - r.last) / 864e5);
      return { k, name, acc, delta, sub: recent ? `${r.w} rep${r.w === 1 ? "" : "s"} this week` : `last practiced ${days === 0 ? "today" : days === 1 ? "yesterday" : `${days} days ago`}` };
    });
  }, [log]);
  if (!log) return null;
  return (
    <section className="card p-5 mb-4">
      <div className="flex items-baseline justify-between mb-1">
        <div className="eyebrow">Your skills</div>
        {rows.length > 0 && <span className="text-[11px]" style={{ color: "var(--muted)" }}>accuracy · last 7 days</span>}
      </div>
      {!rows.length ? (
        <p className="text-sm mt-2" style={{ color: "var(--ivory-d)" }}>Practice any drill and your accuracy for each skill shows up here.</p>
      ) : (
        <div className="-mx-1">
          {rows.map((r, i) => (
            <button key={r.k} onClick={() => go && SKILL_GO[r.k] && go(...SKILL_GO[r.k])} className="skillrow w-full text-left" style={{ borderTop: i ? "1px solid var(--line)" : "none" }}>
              <div className="min-w-0 flex-1">
                <div className="flex items-baseline justify-between gap-3">
                  <span className="text-sm font-medium truncate" style={{ color: "var(--ivory)" }}>{r.name}</span>
                  <span className="flex items-baseline gap-2 shrink-0">
                    {r.delta != null && r.delta !== 0 && <span className="mono text-[11px]" style={{ color: r.delta > 0 ? "var(--brass)" : "var(--neg-l)" }}>{r.delta > 0 ? "▲" : "▼"}{Math.abs(r.delta)}</span>}
                    <span className="mono text-sm font-semibold" style={{ color: skillTone(r.acc) }}>{r.acc}%</span>
                  </span>
                </div>
                <div className="flex items-center gap-3 mt-1.5">
                  <div className="flex-1 h-1.5 rounded-full overflow-hidden" style={{ background: "rgba(var(--fg),.07)" }}><div className="h-full rounded-full bar" style={{ width: `${Math.max(3, r.acc)}%`, background: skillTone(r.acc) }} /></div>
                  <span className="text-[11px] shrink-0" style={{ color: "var(--muted)", minWidth: 118, textAlign: "right" }}>{r.sub}</span>
                </div>
              </div>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ color: "var(--muted)", flex: "none" }}><path d="M9 6l6 6-6 6" /></svg>
            </button>))}
        </div>
      )}
      {rows.length > 0 && <p className="text-[11px] mt-2" style={{ color: "var(--muted)" }}><span style={{ color: "var(--brass)" }}>●</span> 95%+ is casino-ready · <span style={{ color: "var(--rose)" }}>●</span> under 85% needs work. Tap a skill to practice it.</p>}
    </section>
  );
}
